// ratelimit/limiter.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is an injectable time source for deterministic testing.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given capacity and refill rate (tokens/sec).
// The clock parameter must not be nil.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens can be consumed immediately.
// If allowed, n tokens are consumed; otherwise no tokens are consumed.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
