package tokenbucket

import (
	"errors"
	"sync"
	"time"
)

// Clock is an injectable time source for testability.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu         sync.Mutex
	capacity   float64
	tokens     float64
	refillRate float64 // tokens per second
	lastRefill time.Time
	clock      Clock
}

// NewTokenBucket creates a TokenBucket. capacity must be > 0,
// refillRate (tokens/sec) must be > 0, and clock must not be nil.
func NewTokenBucket(capacity, refillRate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("tokenbucket: capacity must be > 0")
	}
	if refillRate <= 0 {
		return nil, errors.New("tokenbucket: refillRate must be > 0")
	}
	if clock == nil {
		return nil, errors.New("tokenbucket: clock must not be nil")
	}
	return &TokenBucket{
		capacity:   capacity,
		tokens:     capacity,
		refillRate: refillRate,
		lastRefill: clock.Now(),
		clock:      clock,
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if successful.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	if elapsed > 0 {
		tb.tokens += elapsed * tb.refillRate
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.lastRefill = now
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is a convenience wrapper for AllowN(1).
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
